@js:
function qimanwu() {
   let disc = [];
let tagHtml = java.ajax(`${source.key}/custom/search`);
  let doc = org.jsoup.Jsoup.parse(tagHtml);
  let tags = doc.select(".groupList li a");
  Array.from(tags).forEach(a => {
    disc.push({
      title: a.text(),
      url: a.attr("href") +"/page/{{page}}",
      style: {
        layout_flexGrow: 1,
        layout_flexBasisPercent: 0.45
      }
    });
  });

  disc.push({
    title: "精品漫画",
    url: "/custom/boutique",
    style: {layout_flexBasisPercent: 1, layout_flexGrow: 0.45}
  });

  disc.push({
    title: "最近更新",
    url: "/custom/update",
    style: {layout_flexBasisPercent: 1, layout_flexGrow: 0.45}
  });

  disc.push({
    title: "热门推荐",
    url: "/custom/recom",
    style: {layout_flexBasisPercent: 1, layout_flexGrow: 0.45}
  });

   return JSON.stringify(disc);
}

const getDate = (time) => 
  new Date(time).toLocaleDateString();

const getTime = (dateStr) => {
  let d;
  try {
    d = new Date(dateStr);
    if (isNaN(d.getTime())) throw new Error('Invalid Date');
  } catch (e) {
    return 0;
  }
  return d.getTime()
}

let discovery;

try {
  let raw = String(source.getVariable()).trim();
  let cache = null;
  if (raw) { try { cache = JSON.parse(raw); } catch (e) {} }

  let now = Date.now();
  let sevenDays = 7 * 24 * 60 * 60 * 1000;

  let isValid = cache
               && cache.date
               && cache.fx !== undefined
               && (now -  getTime(cache.date)) < sevenDays;

  if (isValid) {
    discovery = cache.fx;
  } else {
    discovery = qimanwu();
    let dateStr = getDate(now);
    source.setVariable(JSON.stringify({ date: dateStr, fx: discovery }));
  }
} catch (e) {
  discovery = qimanwu();
  source.setVariable(JSON.stringify({
    date: getDate(now),
    fx: discovery
  }));
}

discovery;

